// Store RPC response topic if present
if (msg.rpcResponseTopic) {
    flow.set("ips_rpc_response_topic", msg.rpcResponseTopic);
}

// Grid phase voltages
// 698: Grid phase voltage A (0.1V)
// 699: Grid phase voltage B (0.1V)
// 700: Grid phase voltage C (0.1V)

msg.baseAddr = 698;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 698,
    quantity: 3
};
return msg;

// Grid side phase powers - LOW words
// 722: Grid A-phase power LOW (1W, S32)
// 723: Grid B-phase power LOW (1W, S32)
// 724: Grid C-phase power LOW (1W, S32)
// 725: Grid total active power LOW (1W, S32)

msg.baseAddr = 722;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 722,
    quantity: 4
};
return msg;

// Grid side phase powers - HIGH words
// 787: Grid A-phase power HIGH (1W, S32)
// 788: Grid B-phase power HIGH (1W, S32)
// 789: Grid C-phase power HIGH (1W, S32)
// 790: Grid total active power HIGH (1W, S32)

msg.baseAddr = 787;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 787,
    quantity: 4
};
return msg;

// Build InverterPhaseState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("InverterPhaseState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to signed 32-bit
function s32(low, high) {
    const u = ((high & 0xFFFF) << 16) | (low & 0xFFFF);
    return (u & 0x80000000) ? u - 0x100000000 : u;
}

// ---- Store partials ----

// Grid Voltage 698-700
if (baseAddr === 698) {
    flow.set("ips_part_voltage", {
        phaseAVoltageV: Math.round((data[0] || 0) * 0.1 * 10) / 10,  // 698
        phaseBVoltageV: Math.round((data[1] || 0) * 0.1 * 10) / 10,  // 699
        phaseCVoltageV: Math.round((data[2] || 0) * 0.1 * 10) / 10   // 700
    });
}

// Grid Power Low 722-725
else if (baseAddr === 722) {
    flow.set("ips_part_power_low", {
        phaseA: data[0] || 0,  // 722
        phaseB: data[1] || 0,  // 723
        phaseC: data[2] || 0,  // 724
        total: data[3] || 0    // 725
    });
}

// Grid Power High 787-790 - Combine with low to form S32
else if (baseAddr === 787) {
    const low = flow.get("ips_part_power_low");
    if (low) {
        flow.set("ips_part_power", {
            phaseAPowerW: s32(low.phaseA, data[0] || 0),  // 722 + 787
            phaseBPowerW: s32(low.phaseB, data[1] || 0),  // 723 + 788
            phaseCPowerW: s32(low.phaseC, data[2] || 0),  // 724 + 789
            totalActivePowerW: s32(low.total, data[3] || 0)  // 725 + 790
        });
    }
}
else {
    return null;
}

// ---- Try to assemble ----

const voltagePart = flow.get("ips_part_voltage");
const powerPart = flow.get("ips_part_power");

if (!voltagePart || !powerPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100";

const state = {
    kind: "InverterPhaseState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    deviceId: deviceId,

    gridSide: {
        phaseA: {
            voltageV: voltagePart.phaseAVoltageV,
            powerW: powerPart.phaseAPowerW
        },
        phaseB: {
            voltageV: voltagePart.phaseBVoltageV,
            powerW: powerPart.phaseBPowerW
        },
        phaseC: {
            voltageV: voltagePart.phaseCVoltageV,
            powerW: powerPart.phaseCPowerW
        },
        totalActivePowerW: powerPart.totalActivePowerW
    }
};

// Clear partials
flow.set("ips_part_voltage", null);
flow.set("ips_part_power_low", null);
flow.set("ips_part_power", null);

flow.set("inverterPhaseStateSnapshot", state);

// Check if this is an RPC request
const rpcTopic = flow.get("ips_rpc_response_topic");
if (rpcTopic) {
    // Send RPC response
    msg.payload = { success: true, data: state };
    msg.topic = rpcTopic;
    flow.set("ips_rpc_response_topic", null);
    return [msg, null];
} else {
    // Send telemetry / debug
    msg.payload = state;
    msg.state = state;
    return [null, msg];
}
